-- Expanded luxury armory: 160+ purchasable cosmetics and 150 XP-gated weapon disciplines.
alter table public.combat_cosmetic_catalog drop constraint if exists combat_cosmetic_catalog_slot_check;
alter table public.combat_cosmetic_catalog add constraint combat_cosmetic_catalog_slot_check check(slot in ('team_color','helmet','visor','armor_style','weapon_skin','aura','eye_glow','armor','weapon'));
alter table public.combat_cosmetic_catalog drop constraint if exists combat_cosmetic_catalog_price_coins_check;
alter table public.combat_cosmetic_catalog add constraint combat_cosmetic_catalog_price_coins_check check(price_coins between 100 and 50000);
alter table public.combat_customizations add column if not exists eye_glow text not null default 'none';
alter table public.combat_customizations add column if not exists aura_style text not null default 'none';
alter table public.combat_customizations add column if not exists armor_variant text not null default 'ronin';
alter table public.combat_customizations add column if not exists weapon_variant text not null default 'void_katana';
insert into public.combat_cosmetic_catalog(id,label,slot,value,price_coins,rarity) values
('team_color:cyan','Cyber Cyan','team_color','cyan',180,'Standard'),('team_color:gold','Imperial Gold','team_color','gold',250,'Premium'),('team_color:violet','Royal Violet','team_color','violet',300,'Premium'),('team_color:emerald','Emerald Pulse','team_color','emerald',300,'Premium'),('helmet:tactical','Tactical Helm','helmet','tactical',400,'Premium'),('helmet:horned','Warlord Horns','helmet','horned',750,'Elite'),('visor:slit','Predator Slit','visor','slit',200,'Standard'),('visor:cross','Crosshair Visor','visor','cross',350,'Premium'),('armor_style:ronin','Ronin Armor','armor_style','ronin',500,'Premium'),('armor_style:heavy','Titan Heavy Plate','armor_style','heavy',700,'Elite'),('armor_style:tech','Aether Exosuit','armor_style','tech',900,'Elite'),('weapon_skin:steel','Polished Steel','weapon_skin','steel',350,'Premium'),('weapon_skin:void','Void Obsidian','weapon_skin','void',600,'Elite'),('weapon_skin:plasma','Plasma Sovereign','weapon_skin','plasma',850,'Elite'),('aura:legendary','Celestial Aura','aura','true',1200,'Legendary')
on conflict(id) do nothing;
-- Fifty auras.
with src as (select item,ord from unnest(array[
'solar_crown|Solar Crown','eventide|Eventide','ion_halo|Ion Halo','aurora_field|Aurora Field','prismatic_wake|Prismatic Wake','singularity|Singularity','starforge|Starforge','blue_shift|Blue Shift','golden_ratio|Golden Ratio','eclipse_mantle|Eclipse Mantle','helios|Helios','lunar_tide|Lunar Tide','nova_bloom|Nova Bloom','gravity_well|Gravity Well','celestial_arc|Celestial Arc','quantum_veil|Quantum Veil','stellar_wind|Stellar Wind','crystal_flux|Crystal Flux','radiant_circuit|Radiant Circuit','obsidian_flare|Obsidian Flare','monolith|Monolith','polar_light|Polar Light','solar_wind|Solar Wind','afterglow|Afterglow','deep_space|Deep Space','white_dwarf|White Dwarf','red_giant|Red Giant','blue_giant|Blue Giant','dark_matter|Dark Matter','event_horizon|Event Horizon','astral_current|Astral Current','meridian|Meridian','zenith|Zenith','equilibrium|Equilibrium','crown_of_light|Crown of Light','night_signal|Night Signal','spectral_tide|Spectral Tide','solar_sentinel|Solar Sentinel','luminous_core|Luminous Core','void_bloom|Void Bloom','astral_drift|Astral Drift','polaris|Polaris','diamond_dust|Diamond Dust','tesseract|Tesseract','infinity_loop|Infinity Loop','royal_ion|Royal Ion','empyrion|Empyrion','cosmic_rain|Cosmic Rain','eternal_sunrise|Eternal Sunrise','apex_aether|Apex Aether'
]) with ordinality as x(item,ord))
insert into public.combat_cosmetic_catalog(id,label,slot,value,price_coins,rarity)
select 'aura:'||split_part(item,'|',1),split_part(item,'|',2),'aura',split_part(item,'|',1),least(50000,9000+ord*850),case when ord<11 then 'Elite' else 'Legendary' end from src on conflict(id) do nothing;
-- Twenty animated eye-fire effects.
with src as (select item,ord from unnest(array['ember|Ember Iris','blue_arc|Blue Arc','white_phosphor|White Phosphor','crimson_trace|Crimson Trace','ion_surge|Ion Surge','plasma_burn|Plasma Burn','solar_flare|Solar Flare','glacier|Glacier','violet_static|Violet Static','acid_lime|Acid Lime','golden_furnace|Golden Furnace','ghostfire|Ghostfire','arc_lightning|Arc Lightning','inferno|Inferno','polar_rift|Polar Rift','blacklight|Blacklight','starcore|Starcore','overdrive|Overdrive','dragon_breath|Dragon Breath','nova_burn|Nova Burn']) with ordinality as x(item,ord))
insert into public.combat_cosmetic_catalog(id,label,slot,value,price_coins,rarity) select 'eye_glow:'||split_part(item,'|',1),split_part(item,'|',2),'eye_glow',split_part(item,'|',1),least(15000,4500+ord*550),case when ord<5 then 'Premium' when ord<14 then 'Elite' else 'Legendary' end from src on conflict(id) do nothing;
-- Twenty armour systems.
with src as (select item,ord from unnest(array['carbon_weave|Carbon Weave','ceramic_shell|Ceramic Shell','titanium_frame|Titanium Frame','lamellar|Lamellar System','cerberus|Cerberus Plate','aegis_prime|Aegis Prime','vector_suit|Vector Suit','stealth_mesh|Stealth Mesh','exoframe|Exoframe','monarch_plate|Monarch Plate','atlas_rig|Atlas Rig','spectre_shell|Spectre Shell','ion_harness|Ion Harness','boreal_guard|Boreal Guard','blacksite|Blacksite Armour','imperial_frame|Imperial Frame','phase_lattice|Phase Lattice','sovereign_plate|Sovereign Plate','aphelion|Aphelion Suit','event_horizon_armor|Event Horizon Armour']) with ordinality as x(item,ord))
insert into public.combat_cosmetic_catalog(id,label,slot,value,price_coins,rarity) select 'armor:'||split_part(item,'|',1),split_part(item,'|',2),'armor',split_part(item,'|',1),least(50000,12000+ord*2000),case when ord<3 then 'Premium' when ord<11 then 'Elite' else 'Legendary' end from src on conflict(id) do nothing;
-- Fifteen signature weapons.
with src as (select item,ord from unnest(array['void_katana|Void Katana','meridian_sabre|Meridian Sabre','blackglass_blade|Blackglass Blade','longline_glaive|Longline Glaive','ion_lance|Ion Lance','monolith_greatsword|Monolith Greatsword','twin_vector|Twin Vector Blades','titan_maul|Titan Maul','arc_repeater|Arc Repeater','phase_bow|Phase Bow','rift_gauntlets|Rift Gauntlets','nova_halberd|Nova Halberd','aether_staff|Aether Staff','sovereign_edge|Sovereign Edge','zero_point|Zero Point']) with ordinality as x(item,ord))
insert into public.combat_cosmetic_catalog(id,label,slot,value,price_coins,rarity) select 'weapon:'||split_part(item,'|',1),split_part(item,'|',2),'weapon',split_part(item,'|',1),least(50000,15000+ord*2500),case when ord<3 then 'Premium' when ord<8 then 'Elite' else 'Legendary' end from src on conflict(id) do nothing;
-- Twenty premium helmets and twenty visors.
insert into public.combat_cosmetic_catalog(id,label,slot,value,price_coins,rarity) values
('helmet:carbon_crown','Carbon Crown','helmet','carbon_crown',4500,'Premium'),('helmet:ceramic_guard','Ceramic Guard','helmet','ceramic_guard',5000,'Premium'),('helmet:sentinel','Sentinel Helmet','helmet','sentinel',6000,'Elite'),('helmet:vector','Vector Shell','helmet','vector',6500,'Elite'),('helmet:monarch','Monarch Helm','helmet','monarch',7000,'Elite'),('helmet:phase','Phase Helmet','helmet','phase',7500,'Elite'),('helmet:blacksite','Blacksite Hood','helmet','blacksite',8000,'Elite'),('helmet:ion','Ion Crown','helmet','ion',8500,'Elite'),('helmet:atlas','Atlas Helmet','helmet','atlas',9000,'Elite'),('helmet:aphelion','Aphelion Mask','helmet','aphelion',9500,'Elite'),('helmet:imperial','Imperial Crest','helmet','imperial',10000,'Legendary'),('helmet:nightglass','Nightglass Helm','helmet','nightglass',11000,'Legendary'),('helmet:polaris','Polaris Shell','helmet','polaris',12000,'Legendary'),('helmet:starforge','Starforge Helm','helmet','starforge',13000,'Legendary'),('helmet:sovereign','Sovereign Mask','helmet','sovereign',14000,'Legendary'),('helmet:zero_point','Zero Point Visage','helmet','zero_point',15000,'Legendary'),('helmet:auric','Auric Sentinel','helmet','auric',16000,'Legendary'),('helmet:prism','Prism Enclosure','helmet','prism',17000,'Legendary'),('helmet:singularity','Singularity Helm','helmet','singularity',18000,'Legendary'),('helmet:apex','Apex Visage','helmet','apex',20000,'Legendary'),
('visor:amberline','Amberline Visor','visor','amberline',3500,'Premium'),('visor:ion_cut','Ion Cut','visor','ion_cut',4000,'Premium'),('visor:arclight','Arclight Visor','visor','arclight',4500,'Premium'),('visor:night_signal','Night Signal Visor','visor','night_signal',5000,'Elite'),('visor:split_prism','Split Prism','visor','split_prism',5500,'Elite'),('visor:crosshair','Crosshair Array','visor','crosshair',6000,'Elite'),('visor:blue_shift','Blue Shift Visor','visor','blue_shift',6500,'Elite'),('visor:gold_trace','Gold Trace','visor','gold_trace',7000,'Elite'),('visor:ghostline','Ghostline','visor','ghostline',7500,'Elite'),('visor:infrared','Infrared Optic','visor','infrared',8000,'Elite'),('visor:polarized','Polarized Glass','visor','polarized',8500,'Elite'),('visor:starcore','Starcore Lens','visor','starcore',9000,'Elite'),('visor:solar_edge','Solar Edge','visor','solar_edge',9500,'Legendary'),('visor:phantom','Phantom Optic','visor','phantom',10000,'Legendary'),('visor:plasma_arc','Plasma Arc','visor','plasma_arc',11000,'Legendary'),('visor:inferno','Inferno Lens','visor','inferno',12000,'Legendary'),('visor:dragon_breath','Dragon Breath Optic','visor','dragon_breath',13000,'Legendary'),('visor:obsidian','Obsidian Lens','visor','obsidian',14000,'Legendary'),('visor:overdrive','Overdrive Optic','visor','overdrive',15000,'Legendary'),('visor:omega','Omega Visor','visor','omega',18000,'Legendary')
on conflict(id) do nothing;
create table if not exists public.combat_weapon_skill_catalog(id text primary key,weapon_id text not null references public.combat_cosmetic_catalog(id) on delete cascade,weapon_name text not null,skill_name text not null,slot_number integer not null check(slot_number between 1 and 10),unlock_xp integer not null check(unlock_xp>=0),description text not null,unique(weapon_id,slot_number));
alter table public.combat_weapon_skill_catalog enable row level security;
drop policy if exists "Weapon skill catalogue readable" on public.combat_weapon_skill_catalog;
create policy "Weapon skill catalogue readable" on public.combat_weapon_skill_catalog for select to authenticated using(true);
grant select on public.combat_weapon_skill_catalog to authenticated;
do $$ declare w record; sk text[]:=array['Opening Form','Guard Splitter','Crosswind','Counterline','Rising Arc','Phase Shift','Precision Break','Overwatch','Momentum Drive','Final Measure']; xp integer[]:=array[1000,2500,4500,7000,10000,14000,19000,25000,33000,45000]; ds text[]:=array['A precise opening attack.','Punishes a guarded opponent.','Repositions before the next strike.','Turns a defended moment into an opening.','Builds momentum through a rising attack.','Shifts position with a controlled burst.','Targets an exposed defensive line.','Improves control of the engagement.','Converts tempo into sustained pressure.','A high-commitment signature technique.']; i integer;
begin for w in select id,label from public.combat_cosmetic_catalog where slot='weapon' loop for i in 1..10 loop
insert into public.combat_weapon_skill_catalog(id,weapon_id,weapon_name,skill_name,slot_number,unlock_xp,description) values(w.id||':skill:'||i,w.id,w.label,w.label||' · '||sk[i],i,xp[i],ds[i]) on conflict(id) do nothing;
end loop; end loop; end $$;
create or replace function public.purchase_combat_cosmetic(p_cosmetic_id text) returns jsonb language plpgsql security definer set search_path=public as $$
declare u uuid:=auth.uid(); c public.combat_cosmetic_catalog%rowtype; balance bigint;
begin if u is null then raise exception 'Authentication required'; end if;
select * into c from public.combat_cosmetic_catalog where id=p_cosmetic_id and active for update;
if not found then raise exception 'Cosmetic is unavailable'; end if;
if exists(select 1 from public.combat_cosmetic_owned where user_id=u and cosmetic_id=c.id) then raise exception 'Already owned'; end if;
perform 1 from public.wallets where user_id=u for update;if not found then raise exception 'Wallet not found';end if;
update public.wallets set coins=coins-c.price_coins,updated_at=now() where user_id=u and coins>=c.price_coins returning coins into balance;
if not found then raise exception 'Not enough coins';end if;
insert into public.combat_cosmetic_owned(user_id,cosmetic_id) values(u,c.id);
insert into public.wallet_transactions(user_id,currency,amount,reason,source) values(u,'coins',-c.price_coins,'Combat cosmetic: '||c.label,'combat_cosmetic_marketplace');
insert into public.combat_customizations(user_id) values(u) on conflict(user_id) do nothing;
if c.slot='team_color' then update public.combat_customizations set team_color=c.value,updated_at=now() where user_id=u;
elsif c.slot='helmet' then update public.combat_customizations set helmet=c.value,updated_at=now() where user_id=u;
elsif c.slot='visor' then update public.combat_customizations set visor=c.value,updated_at=now() where user_id=u;
elsif c.slot='armor_style' then update public.combat_customizations set armor_style=c.value,updated_at=now() where user_id=u;
elsif c.slot='weapon_skin' then update public.combat_customizations set weapon_skin=c.value,updated_at=now() where user_id=u;
elsif c.slot='aura' then update public.combat_customizations set aura=true,aura_style=c.value,updated_at=now() where user_id=u;
elsif c.slot='eye_glow' then update public.combat_customizations set eye_glow=c.value,updated_at=now() where user_id=u;
elsif c.slot='armor' then update public.combat_customizations set armor_variant=c.value,updated_at=now() where user_id=u;
elsif c.slot='weapon' then update public.combat_customizations set weapon_variant=c.value,updated_at=now() where user_id=u;end if;
return jsonb_build_object('success',true,'cosmetic_id',c.id,'label',c.label,'price',c.price_coins,'coins',balance,'rarity',c.rarity);end $$;
revoke all on function public.purchase_combat_cosmetic(text) from public,anon;
grant execute on function public.purchase_combat_cosmetic(text) to authenticated;
alter table public.combat_customizations alter column eye_glow set default 'none';
update public.combat_customizations c set eye_glow='none' where not exists(select 1 from public.combat_cosmetic_owned o where o.user_id=c.user_id and o.cosmetic_id like 'eye_glow:%');
